import {guestFields,isIdentityField,type GuestData,type BillingData} from '@/lib/guests';
export function GuestFields({prefix,data,billing=false,requiredName=false,disabled=false,compact=false}:{prefix:string;data:Partial<GuestData|BillingData>;billing?:boolean;compact?:boolean;requiredName?:boolean;disabled?:boolean}){
 const fields=guestFields.filter(([key])=>!billing||key!=='display_name'&&!isIdentityField(key));
 const renderField=([key,label,max]:typeof guestFields[number])=><label className="field" key={key}>{label}<input name={prefix+key} type={key==='email'?'email':key==='phone'?'tel':['date_of_birth','document_issued','document_expiry'].includes(key)?'date':'text'} required={key==='display_name'&&requiredName} maxLength={max} minLength={key==='country_code'?2:undefined} pattern={key==='country_code'?'[a-zA-Z]{2}':undefined} disabled={disabled} autoComplete="off" defaultValue={(data as Partial<GuestData>)[key]??''}/></label>;
 return compact?<><div className="pilot-guest-fields">{fields.filter(([key])=>['display_name','phone','email'].includes(key)).map(renderField)}</div><details><summary>Address, ID and additional guest details</summary><div className="pilot-guest-fields">{fields.filter(([key])=>!['display_name','phone','email'].includes(key)).map(renderField)}</div></details></>:<div className="pilot-guest-fields">{fields.map(renderField)}</div>;
}
